const S = params.length / 4.3;
const paint = { preset: 'metal', color: params.bodyColor, metalness: 0.5, roughness: 0.25 };
const cream = { preset: 'metal', color: params.fenderColor, metalness: 0.4, roughness: 0.3 };
const chrome = { preset: 'metal', color: '#d8dce2', metalness: 1, roughness: 0.12 };
const rubber = { preset: 'rubber', color: '#161616', roughness: 0.9 };
const dark = { preset: 'metal', color: '#1c1c1f', metalness: 0.5, roughness: 0.6 };
const top = { preset: 'fabric', color: params.topColor, roughness: 0.95 };
const leather = { preset: 'fabric', color: params.seatColor, roughness: 0.7 };
const glass = { preset: 'glass', color: '#9fd0e8', opacity: 0.35, roughness: 0.05 };
const lens = { preset: 'emissive', color: '#fff6c8', emissive: '#fff0b0', emissiveIntensity: 2 };
function A(m, mat) { m.scale(S); api.add(m, mat); }
function C(hx, hy, hz, x, y, z) { api.collider({ kind: 'box', halfExtents: [hx * S, hy * S, hz * S], offset: [x * S, y * S, z * S] }); }
function wheel(x, y, z, spare) {
  const sg = x > 0 ? 1 : -1;
  const place = (m) => { if (spare) { m.translate(x, y, z); } else { m.translate(x, y, z); } return m; };
  const ry = spare ? 0 : 90;
  const rim = (m) => { m.rotate(0, ry, 0); return place(m); };
  A(rim(api.torus(0.31, 0.07)), rubber);
  const ww = api.lathe([[0.22, 0], [0.285, 0], [0.285, 0.02], [0.22, 0.02], [0.22, 0]], 28);
  if (spare) { ww.rotate(90, 0, 0).translate(0, 0, 0.06); } else { ww.rotate(0, 0, 90).translate(sg * 0.06, 0, 0); }
  place(ww);
  A(ww, { preset: 'plastic', color: '#f4f1e6', roughness: 0.6 });
  A(rim(api.torus(0.215, 0.015)), chrome);
  for (let i = 0; i < 10; i++) {
    const sp = api.box(0.015, 0.44, 0.015);
    if (spare) { sp.rotate(0, 0, i * 18); } else { sp.rotate(i * 18, 0, 0); }
    A(place(sp), chrome);
  }
  const hub = api.sphere(0.065, 2);
  if (spare) hub.scale(1, 1, 0.6); else hub.scale(0.6, 1, 1);
  A(place(hub), chrome);
}
const fx = 0.75, zf = 1.2, zr = -1.3;
wheel(fx, 0.38, zf); wheel(-fx, 0.38, zf); wheel(fx, 0.38, zr); wheel(-fx, 0.38, zr);
wheel(0, 0.78, -2.12, true);
A(api.box(0.5, 0.06, 0.1).translate(0, 0.35, -2.12), dark);
A(api.cylinder(0.025, 0.025, 1.5, 8).rotate(0, 0, 90).translate(0, 0.38, zf), dark);
A(api.cylinder(0.025, 0.025, 1.5, 8).rotate(0, 0, 90).translate(0, 0.38, zr), dark);
// chassis
A(api.box(0.7, 0.12, 3.5).translate(0, 0.38, -0.1), dark);
// fenders
function arch() {
  const pts = [];
  for (let a = 215; a >= -35; a -= 12.5) pts.push([Math.cos(a * Math.PI / 180) * 0.53, 0.38 + Math.sin(a * Math.PI / 180) * 0.53]);
  for (let a = -35; a <= 215; a += 12.5) pts.push([Math.cos(a * Math.PI / 180) * 0.45, 0.38 + Math.sin(a * Math.PI / 180) * 0.45]);
  return pts;
}
const ar = arch();
for (const sx of [1, -1]) {
  for (const z of [zf, zr]) {
    A(api.extrude(ar, 0.3).rotate(0, 90, 0).translate(sx * fx, 0, z), cream);
  }
  // running board
  A(api.box(0.26, 0.04, 1.6).translate(sx * 0.7, 0.4, -0.05), dark);
  A(api.box(0.03, 0.045, 1.6).translate(sx * 0.83, 0.4, -0.05), chrome);
  // fender brace to body
  A(api.box(0.22, 0.05, 0.9).translate(sx * 0.62, 0.62, zf + 0.1), cream);
  A(api.box(0.22, 0.05, 0.9).translate(sx * 0.62, 0.62, zr - 0.05), cream);
  // headlamps
  A(api.sphere(0.14, 3).translate(sx * 0.55, 0.98, 1.5), chrome);
  A(api.sphere(0.1, 2).scale(1, 1, 0.5).translate(sx * 0.55, 0.98, 1.62), lens);
  A(api.cylinder(0.02, 0.02, 0.3, 6).translate(sx * 0.55, 0.8, 1.45), chrome);
}
// body
A(api.box(0.95, 0.45, 2.2).translate(0, 0.72, -0.85), paint);
A(api.box(0.8, 0.5, 1.4).translate(0, 0.85, 0.9), paint);
A(api.box(0.7, 0.04, 1.3).translate(0, 1.12, 0.9), paint);
A(api.cylinder(0.3, 0.38, 0.3, 16).scale(1, 1, 1.4).rotate(90, 0, 0).translate(0, 0.78, -2.0), paint);
A(api.box(0.6, 0.06, 1.4).translate(0, 1.15, 0.9), paint);
// hood louvres
for (let i = 0; i < 6; i++) for (const sx of [1, -1]) A(api.box(0.02, 0.18, 0.04).translate(sx * 0.405, 0.9, 0.5 + i * 0.12), chrome);
// grille
A(api.box(0.52, 0.8, 0.07).translate(0, 0.98, 1.63), chrome);
for (let i = -4; i <= 4; i++) A(api.box(0.02, 0.7, 0.04).translate(i * 0.05, 0.98, 1.68), dark);
A(api.box(0.4, 0.07, 0.04).translate(0, 1.4, 1.63), chrome);
A(api.box(0.62, 0.1, 0.05).translate(0, 0.55, 1.6), paint);
// bumpers
A(api.box(1.3, 0.07, 0.05).translate(0, 0.4, 1.85), chrome);
A(api.box(1.1, 0.07, 0.05).translate(0, 0.4, -2.3), chrome);
// windscreen
for (const sx of [1, -1]) {
  const px = sx * 0.26;
  A(api.box(0.4, 0.34, 0.012).rotate(-14, 0, 0).translate(px, 1.33, 0.22), glass);
  A(api.box(0.44, 0.025, 0.03).rotate(-14, 0, 0).translate(px, 1.51, 0.19), chrome);
  A(api.box(0.025, 0.4, 0.03).rotate(-14, 0, 0).translate(sx * 0.46, 1.33, 0.21), chrome);
}
A(api.box(0.03, 0.4, 0.035).rotate(-14, 0, 0).translate(0, 1.33, 0.21), chrome);
A(api.box(0.9, 0.03, 0.04).translate(0, 1.16, 0.28), chrome);
// seats
for (const sx of [1, -1]) {
  A(api.box(0.4, 0.12, 0.45).translate(sx * 0.24, 0.98, -0.3), leather);
  A(api.box(0.4, 0.4, 0.1).rotate(-8, 0, 0).translate(sx * 0.24, 1.2, -0.55), leather);
}
A(api.box(0.85, 0.04, 0.4).translate(0, 0.93, 0.0), dark);
// folded soft top
A(api.box(0.9, 0.18, 0.4).translate(0, 1.07, -1.1), top);
A(api.cylinder(0.14, 0.14, 0.9, 12).rotate(0, 0, 90).translate(0, 1.2, -1.1), top);
A(api.box(0.9, 0.2, 0.05).translate(0, 1.0, -0.9), top);
// tail light
for (const sx of [1, -1]) A(api.sphere(0.05, 2).translate(sx * 0.4, 0.8, -2.0), { preset: 'emissive', color: '#c01818', emissive: '#c01818', emissiveIntensity: 1.5 });
// colliders
C(0.5, 0.35, 1.1, 0, 0.75, -0.85);
C(0.42, 0.4, 0.75, 0, 0.85, 0.9);
C(0.9, 0.2, 2.1, 0, 0.38, -0.1);
return api.build();
